import React from 'react';
import { Link } from 'react-router-dom';
import { products } from '../data/products';

const Products = () => {
  return (
    <div className="products-page">
      <div className="products-header">
        <h1>All Products</h1>
        <p>Browse all available products and open any item for full details.</p>
      </div>

      <div className="products-list-grid">
        {products.map((product) => (
          <article key={product.id} className="products-list-card">
            <Link to={`/products/${product.id}`}>
              <img src={product.image} alt={product.name} className="products-list-image" />
            </Link>
            <div className="products-list-content">
              <h3>
                <Link className="product-link" to={`/products/${product.id}`}>
                  {product.name}
                </Link>
              </h3>
              <p className="products-category">{product.category}</p>
              <div className="products-pricing">
                <span className="products-current">{product.price}</span>
                <span className="products-original">{product.originalPrice}</span>
              </div>
              <Link className="products-view-btn" to={`/products/${product.id}`}>
                View Product
              </Link>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
};

export default Products;
